/* ===== 面板种类（工作区与 Dock 抽屉共用同一套） ===== */
function metaName(k){const m=META.find(x=>x[0]===k);return m?L(m[1],m[2]):k}
function feedTok(t){return `<span class="tk">${esc(t.s)}</span>`}
function tagSrc(kind){return kind==='kol'?`<span class="src k">${I('crown','s12')}KOL</span>`:kind==='trk'?`<span class="src t">${I('eye','s12')}${L('追踪','Tracked')}</span>`:`<span class="src s">${I('brain','s12')}${L('聪明钱','Smart')}</span>`}
const callM=(c,t)=>c.at>0&&t.mc>0?t.mc/c.at:null;
function callHTML(c){const t=BYID.get(c.tk);if(!t)return '';const m=callM(c,t);const mx=c.at>0&&c.max>0?c.max/c.at:null;
 return `<div class="fd" data-t="${t.id}" data-id="${c.id}">${avW(c.name.replace('@',''),c.hue,'')}<div class="bd"><div class="hd"><b>${esc(dn(c.name))}</b>${c.tg?`<span class="src tg">${I('tg','s12')}TG</span>`:`<span class="src" title="X">${I('x','s12')}</span>`}${c.reso?`<span class="src k" title="${L('共振：你设的来源数在你设的时间内都喊了','Resonance (your own thresholds)')}">${L('共振','Reso')}</span>`:''}${c.late?`<span class="xnote" title="${L('雷达看到时已经过了 10 分钟以上：喊单时市值不准，不算倍数','Seen >10 min late; multiple not computed')}">${L('晚到','Late')}</span>`:''}${chChip(t.chain)}<span class="tm">${fAge(nowS()-c.ts)}</span></div>
 <div class="emb">${avP(t)}<div class="mid"><b>${esc(t.s)}</b><span><i class="eml">${L('喊单时','At call')} </i>${fU(c.at)} → <i class="eml">${L('现在','Now')} </i><b class="${m!=null?cls(m-1):''}" data-k="mc">${fU(t.mc)}</b></span></div>${m!=null?`<span class="mult ${m>=1?'up':'dn'}" data-k="mult">${m.toFixed(m>=10?0:2)}x</span>`:''}</div>
 <div class="hold">${mx!=null?`<span>${L('喊单后最高','Max after call')} <b class="up">${mx.toFixed(mx>=10?0:2)}x</b></span>`:''}${c.n>1?`<span>${L(`${c.n} 个来源`,`${c.n} sources`)}</span>`:''}<span style="margin-left:auto"></span>${qbHTML(t)}</div></div></div>`}
function smartHTML(s){const t=BYID.get(s.tk);if(!t)return '';return `<div class="fd" data-t="${t.id}" data-id="${s.id}">${avW(s.name,s.hue,'')}<div class="bd"><div class="hd"><b>${esc(dn(s.name))}</b>${tagSrc(s.kind)}<span class="src ${s.buy?'b':'sl'}">${s.buy?L('买入','Buy'):L('卖出','Sell')}</span><span class="tm">${fAge(nowS()-s.ts)}</span></div>
 <div class="hold">${avP(t,'sm')}<b style="font-family:var(--fUi)">${esc(t.s)}</b><span><b class="${s.buy?'up':'dn'}">${fU(s.usd)}</b></span><span>${L('当时市值','MC then')} <b>${fU(s.mc)}</b></span><span>${L('现在','Now')} <b class="${s.mc!=null&&t.mc!=null?cls(t.mc-s.mc):''}">${fU(t.mc)}</b></span></div></div></div>`}
function sigAgg(){const m=new Map();for(const s of FEED.smart){if(!onChain(s)||!s.buy)continue;const x=m.get(s.tk)||{tk:s.tk,n:0,k:0,first:s.ts,mc:s.mc,w:new Set()};if(!x.w.has(s.w)){x.w.add(s.w);x.n++;if(s.kind==='kol')x.k++}if(s.ts<x.first){x.first=s.ts;x.mc=s.mc}m.set(s.tk,x)}return [...m.values()].filter(x=>x.n>=CNT_2).sort((a,b)=>b.n-a.n)}
/* 读链延迟：用 KOL 动态每一笔的「上链时间 → 雷达看到」实际算中位数（没有足够笔数＝未验证） */
function latOf(ch){const a=FEED.smart.filter(s=>(!ch||BYID.get(s.tk)?.chain===ch)&&s.lat!=null&&s.lat>=0&&s.lat<MS_600).map(s=>s.lat).sort((x,y)=>x-y);if(a.length<CNT_5)return null;return +a[Math.floor(a.length/2)].toFixed(2)}
const LATC=new Proxy({},{get(_,ch){return latOf(ch)}});
