   let body='';if(o.tab==='sig'){const a=sigAgg().filter(x=>o.f==='all'||o.f==='kol'&&x.k||o.f!=='kol');body=a.map(x=>{const t=BYID.get(x.tk);const m=x.mc>0&&t.mc>0?t.mc/x.mc:null;return `<div class="sig" data-t="${t.id}">${avP(t)}<div><b>${esc(t.s)}</b> <span class="t3">${esc(t.n)}</span><div class="t2" style="font-size:11px;margin-top:2px">${L(`${x.n} 个聪明钱买入`,`${x.n} smart wallets bought`)}${x.k?L(`，含 ${x.k} 个 KOL`,`, ${x.k} KOL`):''}</div></div>${m!=null?`<span class="mult ${m>=1?'up':'dn'}">${m.toFixed(2)}x</span>`:'<span></span>'}<div class="ln2"><span>${L('讯号时','At signal')} <b>${fU(x.mc)}</b></span><span>→ ${L('现在','Now')} <b class="${m!=null?cls(m-1):''}">${fU(t.mc)}</b></span><span>${fAge(nowS()-x.first)}${L('前','')}</span>${spark(t,70,18)}<span style="margin-left:auto"></span>${qbHTML(t)}</div></div>`}).join('')||`<div class="empty">${L('目前没有讯号','No signals')}</div>`}
