function splitDrag(e,sp){e.preventDefault();sp.setPointerCapture(e.pointerId);sp.classList.add('drag');const ws=$('#ws');const isV=sp.classList.contains('vs');const ci=+sp.dataset.ci;
 let a,b,ea,eb;if(isV){a=ST.lay.cols[ci-1];b=ST.lay.cols[ci];ea=ws.querySelector(`.wcol[data-ci="${ci-1}"]`);eb=ws.querySelector(`.wcol[data-ci="${ci}"]`)}else{const c=ST.lay.cols[ci];const pi=+sp.dataset.pi;a=c.ps[pi-1];b=c.ps[pi];ea=INST.get(a.id).el;eb=INST.get(b.id).el}
 /* 拖的时候只移动一条导引线（不重排面板内容，稳定 60fps），放开才套用 */
 const wr=ws.getBoundingClientRect(),ra=ea.getBoundingClientRect(),rb=eb.getBoundingClientRect();const ka=isV?'w':'h';const tot=a[ka]+b[ka];const size=isV?rb.right-ra.left:rb.bottom-ra.top;const minPx=isV?PMIN-20:90;
 const g=$('.guide',ws);g.style.display='block';if(isV){g.style.cssText+=`;top:${ra.top-wr.top}px;height:${ra.height}px;width:2px;left:0`}else{g.style.cssText+=`;left:${ra.left-wr.left}px;width:${ra.width}px;height:2px;top:0`}
 const lab=$('b',g);let pa=isV?ra.width:ra.height,raf=0,last=isV?e.clientX:e.clientY;const start=last,sa=pa;
 const put=()=>{raf=0;pa=clamp(sa+(last-start),minPx,size-minPx);const pos=(isV?ra.left-wr.left:ra.top-wr.top)+pa+2;g.style.transform=isV?`translateX(${pos}px)`:`translateY(${pos}px)`;lab.textContent=`${Math.round(pa)} / ${Math.round(size-pa)} px`};put();
 const mv=ev=>{last=isV?ev.clientX:ev.clientY;if(!raf)raf=requestAnimationFrame(put)};
 const up=()=>{sp.classList.remove('drag');sp.removeEventListener('pointermove',mv);cancelAnimationFrame(raf);put();g.style.display='none';g.style.transform='';a[ka]=tot*pa/size;b[ka]=tot-a[ka];ea.style.flexGrow=a[ka];eb.style.flexGrow=b[ka];ST.lay.preset='';$$('.wpre button').forEach(b=>b.classList.remove('on'));saveLayout();for(const [,x] of INST)x.h.resize&&x.h.resize()};
 sp.addEventListener('pointermove',mv);sp.addEventListener('pointerup',up,{once:true});sp.addEventListener('pointercancel',up,{once:true})}
function moveDrag(e,pel){const sx=e.clientX,sy=e.clientY;const id=pel.dataset.id;const x=INST.get(id);let started=false,gh=null,tgt=null,raf=0,lx=sx,ly=sy;const ws=$('#ws');const drop=$('.drop',ws);const wr=ws.getBoundingClientRect();
 const mv=ev=>{lx=ev.clientX;ly=ev.clientY;if(!started){if(Math.hypot(lx-sx,ly-sy)<CNT_5)return;started=true;pel.classList.add('ghosted');gh=document.createElement('div');gh.className='dghost';gh.innerHTML=`${I(PT[x.p.t].ic)}${L(PT[x.p.t].zh,PT[x.p.t].en)}`;ROOTEL.appendChild(gh);document.body.style.cursor='grabbing'}
  if(!raf)raf=requestAnimationFrame(()=>{raf=0;gh.style.transform=`translate(${lx+12}px,${ly+10}px)`;tgt=null;const els=$$('#ws .pnl').filter(p=>p!==pel);let best=null;for(const p of els){const r=p.getBoundingClientRect();if(lx>=r.left&&lx<=r.right&&ly>=r.top&&ly<=r.bottom){best=[p,r];break}}
   let box=null;if(best){const [p,r]=best;const fx=(lx-r.left)/r.width,fy=(ly-r.top)/r.height;const [ci,pi]=findP(p.dataset.id);
    if(fx<PX_0P2){tgt={k:'col',ci};box=[r.left,r.top,r.width*.3,r.height]}else if(fx>PX_0P8){tgt={k:'col',ci:ci+1};box=[r.right-r.width*.3,r.top,r.width*.3,r.height]}else if(fy<PX_0P5){tgt={k:'in',ci,pi};box=[r.left,r.top,r.width,r.height*.45]}else{tgt={k:'in',ci,pi:pi+1};box=[r.left,r.top+r.height*.55,r.width,r.height*.45]}}
   else if(lx>wr.left&&lx<wr.right&&ly>wr.top&&ly<wr.bottom){const cs=$$('#ws .wcol');const last=cs.at(-1).getBoundingClientRect();if(lx>last.right-8){tgt={k:'col',ci:cs.length};box=[last.right-60,last.top,60,last.height]}}
   if(box){drop.style.display='block';drop.style.left=(box[0]-wr.left)+'px';drop.style.top=(box[1]-wr.top)+'px';drop.style.width=box[2]+'px';drop.style.height=box[3]+'px'}else drop.style.display='none'})};
 const up=()=>{removeEventListener('pointermove',mv);removeEventListener('pointerup',up);document.body.style.cursor='';if(!started)return;cancelAnimationFrame(raf);gh.remove();pel.classList.remove('ghosted');drop.style.display='none';if(!tgt)return;
  const [oci,opi]=findP(id);const P=ST.lay.cols[oci].ps[opi];const cols=ST.lay.cols;
  if(tgt.k==='in'){if(tgt.ci===oci&&(tgt.pi===opi||tgt.pi===opi+1))return;let pi=tgt.pi;if(tgt.ci===oci&&opi<pi)pi--;cols[oci].ps.splice(opi,1);cols[tgt.ci].ps.splice(pi,0,P);P.h=1/Math.max(1,cols[tgt.ci].ps.length-1)}
  else{if(cols[oci].ps.length===1&&(tgt.ci===oci||tgt.ci===oci+1))return;cols[oci].ps.splice(opi,1);const w=Math.min(34,100/(cols.length+1));cols.splice(tgt.ci,0,{w,ps:[P]});P.h=1}
  normCols();ST.lay.preset='';renderWS();for(const [,q] of INST)q.h.resize&&q.h.resize()};
 addEventListener('pointermove',mv);addEventListener('pointerup',up)}

/* ===== Dock 抽屉：跟工作区同一套面板 ===== */
/* 底栏：雷达独有的放最前面（铸造、哨兵、TG 遥控、AI 加功能），再来盯盘、最后是我的；不照抄别家底栏的顺序和名称 */
const DOCK=[['@mint','铸造监控','Mint watch','pkg'],['@sentry','安全哨兵','Sentry','shield'],['@tg','TG 遥控','TG remote','send'],['@ai','AI 加功能','AI add-ons','code'],'|',['kolfeed','KOL 动态','KOL live','brain'],['calls','喊单流','Calls','chat'],['signals','讯号','Signals','radar'],['trench','新币','New pairs','cols'],['meta','板块','Sectors','tag'],'|',['pos','持仓','Positions','wallet'],['watch','自选','Watchlist','star'],['wallet','钱包追踪','Wallets','eye'],['alerts','提醒','Alerts','bell'],['monitor','异动','Movers','radio']];
const DOCKACT={'@mint':()=>{ST.newTab='mint';openPage('new')},'@sentry':()=>legShow('sentry'),'@tg':()=>legShow('phone'),'@ai':()=>openPage('ai')};
const DRW={t:null,h:null,p:null,badge:{calls:0,kolfeed:0}};
function paintDock(){const d=$('#dock');const src=isOwnTrade(ST.chain)||ST.chain==='sol'?L('雷达看盘（读链＋AVE 共用看盘）','Radar board (on-chain + shared AVE board)'):L('AVE 共用看盘（经转接站）','Shared AVE board (via relay)');d.innerHTML=`<div class="dks">${DOCK.map(x=>x==='|'?'<span class="dsep"></span>':`<button class="dk${DRW.t===x[0]?' on':''}${x[0][0]==='@'?' ex':''}" data-dk="${x[0]}"${x[0][0]==='@'?` title="${L('雷达独有','Radar exclusive')}"`:''}>${I(x[3])}<span>${L(x[1],x[2])}</span>${DRW.badge[x[0]]?`<span class="bdg">${DRW.badge[x[0]]}</span>`:''}</button>`).join('')}</div><div class="pxs"><button class="stt${ST.err?' bad':''}" data-a="health" title="${L('资料健康：点开看每个资料源','Data health')}"><span class="lv"></span><span class="ssrc">${ST.err?L('资料源断线','Source down'):src}</span> <span class="num t3" id="lat"></span></button></div>`}
function openDrawer(t){const dr=$('#drw');if(DRW.t===t){closeDrawer();return}if(DRW.h&&DRW.h.dispose)DRW.h.dispose();if(DRW.h&&DRW.h.destroy)DRW.h.destroy();DRW.t=t;DRW.badge[t]=0;DRW.p={id:'drawer',t,h:1,o:PT[t].def()};const T=PT[t];
 dr.innerHTML=`<div class="ph"><button class="tt">${`<span class="ic">${I(T.ic)}</span>`}${L(T.zh,T.en)}</button><div class="acts"><button class="hb" data-a="pin">${I('pin')}${L('钉到工作区','Pin to workspace')}</button><button class="hb" data-a="x" title="Esc">${I('close')}</button></div></div><div class="pb"></div>`;
 DRW.h=T.mount($('.pb',dr),DRW.p)||{};dr.classList.add('on');$('#drwv').classList.add('on');paintDock()}
function closeDrawer(){$('#drw').classList.remove('on');$('#drwv').classList.remove('on');const h=DRW.h;DRW.t=null;setTimeout(()=>{if(!DRW.t){if(h&&h.dispose)h.dispose();if(h&&h.destroy)h.destroy();if(DRW.h===h){DRW.h=null;$('#drw').innerHTML=''}}},240);paintDock()}
